SELECT all_covariates.cohort_definition_id,
  all_covariates.covariate_id,
  all_covariates.sum_value,
  CAST(all_covariates.sum_value / (1.0 * total.total_count) AS FLOAT) AS average_value
FROM (SELECT cohort_definition_id, covariate_id, sum_value FROM #cov_1
 UNION ALL
SELECT cohort_definition_id, covariate_id, sum_value FROM #cov_3
 UNION ALL
SELECT cohort_definition_id, covariate_id, sum_value FROM #cov_4
 UNION ALL
SELECT cohort_definition_id, covariate_id, sum_value FROM #cov_8
 UNION ALL
SELECT cohort_definition_id, covariate_id, sum_value FROM #cov_11
) all_covariates
INNER JOIN (
SELECT cohort_definition_id, COUNT(*) AS total_count
FROM @characterization_cohort  GROUP BY cohort_definition_id
) total
  ON all_covariates.cohort_definition_id = total.cohort_definition_id;
